1	"use client";
2	
3	import { useState, useRef, useEffect, useLayoutEffect, useCallback } from "react";
4	import Link from "next/link";
5	import WarpLogoFull from "./icons/WarpLogoFull";
6	import WarpMark from "./icons/WarpMark";
7	import OzMark from "./icons/OzMark";
8	import AppleIcon from "./icons/AppleIcon";
9	import GitHubIcon from "./icons/GitHubIcon";
10	import ChevronDownIcon from "./icons/ChevronDownIcon";
11	import ChevronRightIcon from "./icons/ChevronRightIcon";
12	import ChevronDownLgIcon from "./icons/ChevronDownLgIcon";
13	import HamburgerIcon from "./icons/HamburgerIcon";
14	import XMarkIcon from "./icons/XMarkIcon";
15	import ShieldCheckIcon from "./icons/ShieldCheckIcon";
16	import FileTextIcon from "./icons/FileTextIcon";
17	import CodeIcon from "./icons/CodeIcon";
18	import GitBranchIcon from "./icons/GitBranchIcon";
19	import PencilIcon from "./icons/PencilIcon";
20	import UsersIcon from "./icons/UsersIcon";
21	import CalendarIcon from "./icons/CalendarIcon";
22	import ListDotsIcon from "./icons/ListDotsIcon";
23	import MapIcon from "./icons/MapIcon";
