30	import ExternalLinkIcon from "./icons/ExternalLinkIcon";
31	
32	type FlyoutItem = {
33	  label: string;
34	  description: string;
35	  href: string;
36	  icon: React.ReactNode;
37	  external?: boolean;
38	};
39	
40	const productsItems: FlyoutItem[] = [
41	  {
42	    label: "Warp Terminal",
43	    description: "A modern terminal for agentic coding",
44	    href: "/terminal",
45	    icon: (
46	      <span className="no-frame inline-flex size-6 shrink-0 items-center justify-center rounded-md bg-[#0b0b0b] text-white shadow-[inset_0_0_0_1px_#1f1f1f]">
47	        <WarpMark className="size-3.5" />
48	      </span>
49	    ),
50	  },
51	  {
52	    label: "Warp Agent",
53	    description: "The orchestration-native coding agent",
54	    href: "/agents/warp-agent",
55	    icon: (
56	      <span className="no-frame inline-flex size-6 shrink-0 items-center justify-center rounded-md bg-[#1c1a26] text-[#c7aeff] shadow-[inset_0_0_0_1px_#373245]">
57	        <WarpMark className="size-3.5" />
58	      </span>
59	    ),
60	  },
61	  {
62	    label: "Oz Agent Platform",
63	    description: "The cloud orchestration platform",
64	    href: "/oz",
65	    icon: (
66	      <span className="no-frame inline-flex size-6 shrink-0 items-center justify-center rounded-md bg-[#bda6f7] text-[#111111]">
67	        <OzMark className="size-4" />
68	      </span>
69	    ),
70	  },
