72	
73	const solutionsUseCaseItems: FlyoutItem[] = [
74	  { label: "Code Review", description: "First-pass review on every PR", href: "/use-cases/code-review", icon: <CodeIcon className="size-4" /> },
75	  { label: "Bug Investigation", description: "Reproduce bugs and route fixes", href: "/use-cases/bug-investigation", icon: <FileTextIcon className="size-4" /> },
76	  { label: "Refactors & Migration", description: "Scope, migrate, and validate changes", href: "/use-cases/refactors", icon: <GitBranchIcon className="size-4" /> },
77	  { label: "Incident Response", description: "Investigate alerts and summarize next steps", href: "/use-cases/incident-response", icon: <LightningIcon className="size-4" /> },
78	];
79	
80	const solutionsIndustryItems: FlyoutItem[] = [
81	  { label: "Financial Services", description: "Secure, compliant AI development", href: "/enterprise/financial-services", icon: <ShieldCheckIcon className="size-4" /> },
82	  { label: "Insurance", description: "Modernize policy & claims systems", href: "/enterprise/insurance", icon: <ShieldCheckIcon className="size-4" /> },
83	  { label: "Telecommunications", description: "Scale with your network", href: "/enterprise/telecommunications", icon: <GlobeIcon className="size-4" /> },
84	];
85	
86	const resourceDevItems: FlyoutItem[] = [
87	  { label: "Docs", description: "API docs and guides", href: "https://docs.warp.dev/", icon: <FileTextIcon className="size-4" /> },
88	  { label: "Blog", description: "News and product updates", href: "/blog", icon: <PencilIcon className="size-4" /> },
89	  { label: "Community", description: "Get help and connect", href: "https://docs.warp.dev/support-and-community", icon: <UsersIcon className="size-4" /> },
90	  { label: "Events", description: "Webinars and sessions", href: "https://luma.com/warpdotdev", icon: <CalendarIcon className="size-4" />, external: true },
91	  { label: "Changelog", description: "What's new in Warp", href: "https://docs.warp.dev/changelog", icon: <ListDotsIcon className="size-4" /> },
92	  { label: "Roadmap", description: "See what we're building next", href: "https://github.com/warpdotdev/warp/issues?q=state:open%20label:%22roadmap%22", icon: <MapIcon className="size-4" />, external: true },
93	  { label: "Support", description: "Help and issue tracking", href: "https://docs.warp.dev/support-and-community", icon: <ShieldCheckIcon className="size-4" /> },
94	];
95	
96	const resourceCompanyItems: FlyoutItem[] = [
97	  { label: "About", description: "Our mission and team", href: "/about", icon: <SparklesIcon className="size-4" /> },
98	  { label: "How We Work", description: "Our culture and values", href: "https://notion.warp.dev/", icon: <BookOpenIcon className="size-4" /> },
99	  { label: "Careers", description: "Join the team at Warp", href: "/careers", icon: <BriefcaseIcon className="size-4" /> },
100	  { label: "Press", description: "Media coverage and press kit", href: "/press", icon: <NewspaperIcon className="size-4" /> },
101	  { label: "Research", description: "Reports and insights", href: "/research", icon: <FileTextIcon className="size-4" /> },
102	  { label: "Newsroom", description: "Announcements and press releases", href: "/newsroom", icon: <LightningIcon className="size-4" /> },
103	];
104	
105	const enterpriseItems: FlyoutItem[] = [
106	  { label: "Overview", description: "Secure, compliant agentic development for your org", href: "/enterprise", icon: <ShieldCheckIcon className="size-4" /> },
107	  { label: "Customers", description: "Teams shipping faster with Warp", href: "/customers", icon: <UsersIcon className="size-4" /> },
108	];
109	
110	function FlyoutItemRow({ item, hoverOnWrapper }: { item: FlyoutItem; hoverOnWrapper?: boolean }) {
111	  const external = !!item.external;
112	  const anchor = (
113	    <a
114	      href={item.href}
115	      target={external ? "_blank" : undefined}
116	      rel={external ? "noopener noreferrer" : undefined}
117	      className={
118	        hoverOnWrapper
119	          ? "flex items-start gap-3 rounded-lg p-3 focus:outline-none focus-visible:ring-2 focus-visible:ring-(--color-text)"
120	          : "group flex items-start gap-3 rounded-lg p-3 hover:bg-(--color-text)/5 focus:outline-none focus-visible:ring-2 focus-visible:ring-(--color-text)"
121	      }
122	    >
123	      <span className="mt-0.5 inline-flex size-6 shrink-0 items-center justify-center rounded-md bg-(--color-text)/5 text-(--color-text-secondary) ring-1 ring-inset ring-(--color-border)">
124	        {item.icon}
125	      </span>
126	      <span>
127	        <span className="inline-flex items-center gap-1 text-sm font-semibold text-(--color-text)">
128	          {item.label}
129	          {external && <ExternalLinkIcon className="size-3.5 shrink-0" />}
130	        </span>
131	        <span className="block text-sm text-(--color-muted)">{item.description}</span>
132	      </span>
133	    </a>
134	  );
135	  if (hoverOnWrapper) {
136	    return <div className="group rounded-lg hover:bg-(--color-text)/5">{anchor}</div>;
137	  }
138	  return anchor;
139	}
140	
141	function FlyoutItemProduct({ item }: { item: FlyoutItem }) {
142	  return (
143	    <a
144	      href={item.href}
145	      className="group flex items-start gap-3 rounded-lg p-3 hover:bg-(--color-text)/5"
146	    >
147	      <span className="mt-0.5 inline-flex size-6 shrink-0 items-center justify-center">
148	        {item.icon}
149	      </span>
150	      <div>
151	        <p className="inline-flex items-center gap-1 text-sm font-semibold text-(--color-text)">{item.label}</p>
152	        <p className="mt-0.5 text-sm text-(--color-muted)">{item.description}</p>
153	      </div>
154	    </a>
155	  );
156	}
157	
158	function TwoColumnFlyout({ columns }: { columns: { title: string; items: FlyoutItem[] }[] }) {
159	  return (
160	    <div className="flex divide-x divide-(--color-border) p-2 *:flex-1 [&>*:first-child]:pr-4 [&>*:not(:first-child)]:pl-4">
161	      {columns.map(col => (
162	        <div key={col.title} className="min-w-44">
163	          <div className="mb-1 flex items-center justify-between gap-2 px-3 py-1">
164	            <span className="font-mono text-xs font-medium uppercase tracking-wider text-(--color-muted)">{col.title}</span>
165	          </div>
166	          <div className="flex flex-col">
167	            {col.items.map(item => (
168	              <FlyoutItemRow key={item.label} item={item} hoverOnWrapper />
169	            ))}
170	          </div>
171	        </div>
172	      ))}
173	    </div>
174	  );
175	}
176	
177	// Run before paint on the client (avoids a position flash) but fall back to a
178	// plain effect during SSR so React doesn't warn about useLayoutEffect.
179	const useIsomorphicLayoutEffect = typeof window !== "undefined" ? useLayoutEffect : useEffect;
180	
181	
182	const flyoutPanelBase = "navbar-flyout fixed left-6 top-[calc(var(--scroll-padding-top)-0.75rem)] z-[9999] origin-top-left rounded-[calc(var(--radius)*3)] bg-(--color-background) p-2 shadow-lg ring-1 ring-(--color-border)";
183	const flyoutSmallWidth = "w-max max-w-[calc(100vw-3rem)] lg:max-w-2xl";
184	const flyoutWideWidth = "w-[calc(100vw-3rem)] max-w-3xl";
185	
186	type ActiveFlyout = "products" | "solutions" | "resources" | "enterprise" | null;
187	
188	type FlyoutConfig = {
189	  name: Exclude<ActiveFlyout, null>;
190	  label: string;
191	  width: string;
192	  content: React.ReactNode;
193	  mobileContent: React.ReactNode;
194	};
195	
196	const flyouts: FlyoutConfig[] = [
197	  {
198	    name: "products",
199	    label: "Products",
200	    width: flyoutSmallWidth,
201	    content: productsItems.map(item => <FlyoutItemProduct key={item.label} item={item} />),
202	    mobileContent: productsItems.map(item => <FlyoutItemProduct key={item.label} item={item} />),
203	  },
204	  {
205	    name: "solutions",
206	    label: "Solutions",
207	    width: flyoutWideWidth,
208	    content: (
209	      <TwoColumnFlyout
210	        columns={[
211	          { title: "Use Cases", items: solutionsUseCaseItems },
212	          { title: "Industry", items: solutionsIndustryItems },
213	        ]}
214	      />
215	    ),
216	    mobileContent: [...solutionsUseCaseItems, ...solutionsIndustryItems].map(item => (
217	      <FlyoutItemRow key={item.label} item={item} />
218	    )),
219	  },
220	  {
221	    name: "resources",
222	    label: "Resources",
223	    width: flyoutWideWidth,
224	    content: (
225	      <TwoColumnFlyout
226	        columns={[
227	          { title: "Developers", items: resourceDevItems },
228	          { title: "Company", items: resourceCompanyItems },
229	        ]}
230	      />
231	    ),
232	    mobileContent: [...resourceDevItems, ...resourceCompanyItems].map(item => (
233	      <FlyoutItemRow key={item.label} item={item} />
234	    )),
235	  },
236	  {
237	    name: "enterprise",
238	    label: "Enterprise",
239	    width: flyoutSmallWidth,
240	    content: enterpriseItems.map(item => <FlyoutItemRow key={item.label} item={item} />),
241	    mobileContent: enterpriseItems.map(item => <FlyoutItemRow key={item.label} item={item} />),
242	  },
243	];
244	
245	function DesktopFlyout({
246	  config,
247	  activeFlyout,
248	  openFlyout,
249	  toggleFlyout,
250	  cancelLeave,
251	  scheduleLeave,
252	}: {
253	  config: FlyoutConfig;
254	  activeFlyout: ActiveFlyout;
255	  openFlyout: (name: ActiveFlyout) => void;
256	  toggleFlyout: (name: ActiveFlyout) => void;
257	  cancelLeave: () => void;
258	  scheduleLeave: () => void;
259	}) {
260	  const { name, label, width, content } = config;
261	  return (
262	    <div
263	      className="relative flex items-center self-center"
264	      onMouseEnter={() => openFlyout(name)}
265	      onMouseLeave={scheduleLeave}
266	    >
267	      <button
268	        data-flyout-trigger={name}
269	        onClick={() => toggleFlyout(name)}
270	        className="inline-flex cursor-default items-center gap-1 rounded-lg px-2.5 py-1 text-sm/7 font-medium text-(--color-text) hover:bg-text/5"
271	      >
272	        {label}
273	        <ChevronDownIcon className={`mt-0.5 size-4 opacity-50 transition-transform duration-200 ${activeFlyout === name ? "rotate-180" : ""}`} />
274	      </button>
275	      <div
276	        data-flyout-panel={name}
277	        data-open={activeFlyout === name || undefined}
278	        inert={activeFlyout !== name}
279	        className={`${flyoutPanelBase} ${width}`}
280	        onMouseEnter={cancelLeave}
281	        onMouseLeave={scheduleLeave}
282	      >
283	        {content}
284	      </div>
285	    </div>
286	  );
287	}
288	
289	function MobileAccordion({ label, children }: { label: string; children: React.ReactNode }) {
290	  return (
291	    <details className="group">
292	      <summary className="flex cursor-pointer list-none items-center justify-between text-3xl/10 font-medium text-(--color-text)">
293	        {label}<ChevronDownLgIcon className="size-5 opacity-50 transition-transform group-open:rotate-180" />
294	      </summary>
295	      <div className="mt-4 flex flex-col gap-1 pl-1">
296	        {children}
297	      </div>
298	    </details>
299	  );
300	}
301	
302	export default function Navbar() {
303	  const [activeFlyout, setActiveFlyout] = useState<ActiveFlyout>(null);
304	  const [mobileOpen, setMobileOpen] = useState(false);
305	  const navRef = useRef<HTMLDivElement>(null);
306	  const leaveTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
307	
308	  useEffect(() => {
309	    function handleClickOutside(e: MouseEvent) {
310	      if (!navRef.current?.contains(e.target as Node)) {
311	        setActiveFlyout(null);
312	      }
313	    }
314	    document.addEventListener("mousedown", handleClickOutside);
315	    return () => document.removeEventListener("mousedown", handleClickOutside);
316	  }, []);
317	
318	  useEffect(() => {
319	    document.body.classList.toggle("overflow-hidden", mobileOpen);
320	    return () => { document.body.classList.remove("overflow-hidden"); };
321	  }, [mobileOpen]);
322	
323	  useEffect(() => {
324	    const onKey = (e: KeyboardEvent) => {
325	      if (e.key !== "d" && e.key !== "D") return;
326	      if (e.metaKey || e.ctrlKey || e.altKey) return;
327	      const target = e.target as HTMLElement | null;
328	      if (target?.closest("input, textarea, select, [contenteditable='true']")) return;
329	      e.preventDefault();
330	      window.open(
331	        "/",
332	        "_blank",
333	        "noopener,noreferrer"
334	      );
335	    };
336	    document.addEventListener("keydown", onKey);
337	    return () => document.removeEventListener("keydown", onKey);
338	  }, []);
339	
340	  const cancelLeave = useCallback(() => {
341	    if (leaveTimerRef.current) clearTimeout(leaveTimerRef.current);
342	  }, []);
343	
344	  const scheduleLeave = useCallback(() => {
345	    leaveTimerRef.current = setTimeout(() => setActiveFlyout(null), 200);
346	  }, []);
347	
348	  const openFlyout = useCallback((name: ActiveFlyout) => {
349	    cancelLeave();
350	    setActiveFlyout(name);
351	  }, [cancelLeave]);
352	
353	  const toggleFlyout = (name: ActiveFlyout) => {
354	    setActiveFlyout(prev => prev === name ? null : name);
355	  };
356	
357	  // Position the open flyout like the real site: anchored to its trigger button,
358	  // but clamped so it never overflows the 1.5rem viewport gutter on either side.
359	  // left = clamp(gutter, buttonLeft, viewportWidth - gutter - panelWidth)
360	  useIsomorphicLayoutEffect(() => {
361	    if (!activeFlyout) return;
362	    const nav = navRef.current;
363	    if (!nav) return;
364	    const panel = nav.querySelector<HTMLElement>(`[data-flyout-panel="${activeFlyout}"]`);
365	    const trigger = nav.querySelector<HTMLElement>(`[data-flyout-trigger="${activeFlyout}"]`);
366	    if (!panel || !trigger) return;
367	
368	    const position = () => {
369	      const gutter = 24; // 1.5rem
370	      const btn = trigger.getBoundingClientRect();
371	      const width = panel.offsetWidth;
372	      const maxLeft = window.innerWidth - gutter - width;
373	      const left = Math.max(gutter, Math.min(btn.left, maxLeft));
374	      // The sticky <header>'s backdrop-filter makes this fixed panel positioned
375	      // relative to the header, not the viewport. Rather than guess which ancestor
376	      // is the containing block, measure it: park the panel at 0,0 and read where
377	      // that lands, then offset our viewport-space targets by that origin.
378	      panel.style.left = "0px";
379	      panel.style.top = "0px";
380	      const origin = panel.getBoundingClientRect();
381	      panel.style.left = `${left - origin.left}px`;
382	      panel.style.top = `${btn.bottom + 11 - origin.top}px`;
383	    };
384	
385	    position();
386	    window.addEventListener("resize", position);
387	    return () => window.removeEventListener("resize", position);
388	  }, [activeFlyout]);
389	
390	  return (
391	    <header className="sticky top-0 z-10 bg-background/70 backdrop-blur-md supports-backdrop-filter:bg-background/60">
392	      <nav ref={navRef}>
393	        <div className="mx-auto flex h-(--scroll-padding-top) max-w-7xl items-center gap-4 px-6 lg:px-10">
394	          <div className="flex flex-1 items-center gap-12">
395	            <div className="flex items-center">
396	              <Link href="/" className="inline-flex items-stretch">
397	                <WarpLogoFull className="hidden h-5 w-auto lg:block" />
398	                <WarpMark className="h-6 w-auto lg:hidden" />
399	              </Link>
400	            </div>
401	
402	            {/* Desktop nav — items-stretch so each wrapper fills the full nav height */}
403	            <div className="flex items-stretch gap-1 max-lg:hidden">
404	
405	              {flyouts.map(config => (
406	                <DesktopFlyout
407	                  key={config.name}
408	                  config={config}
409	                  activeFlyout={activeFlyout}
410	                  openFlyout={openFlyout}
411	                  toggleFlyout={toggleFlyout}
412	                  cancelLeave={cancelLeave}
413	                  scheduleLeave={scheduleLeave}
414	                />
415	              ))}
416	
417	              {/* Pricing */}
418	              <div className="flex items-center">
419	                <Link
420	                  href="/pricing"
421	                  className="inline-flex items-center justify-between gap-2 rounded-lg px-2.5 py-1 text-sm/7 font-medium text-(--color-text) hover:bg-text/5"
422	                >
423	                  Pricing
424	                </Link>
425	              </div>
426	            </div>
427	          </div>
428	
429	          {/* Right side */}
430	          <div className="flex flex-1 items-center justify-end gap-4">
431	            <div className="flex shrink-0 items-center gap-5">
